('de-l277-5',276,'die Öffnungszeiten des Museums','de'),
('de-l277-6',276,'Das ist das Fahrrad meiner Schwester.','de'),
('de-l278-1',277,'der Student','de'),
('de-l278-2',277,'Ich kenne den Studenten.','de'),
('de-l278-3',277,'Ich helfe dem Studenten.','de'),
('de-l278-4',277,'Das ist mein Kollege.','de'),
('de-l278-5',277,'Ich frage meinen Kollegen.','de'),
('de-l278-6',277,'Wir sprechen mit dem Menschen.','de'),
('de-l279-1',278,'Das ist der Mann, der hier wohnt.','de'),
('de-l279-2',278,'Das ist die Frau, die Deutsch unterrichtet.','de'),
('de-l279-3',278,'Das ist das Kind, das dort spielt.','de'),
('de-l279-4',278,'Das sind die Leute, die uns helfen.','de'),
('de-l279-5',278,'Ich kenne einen Arzt, der Englisch spricht.','de'),
('de-l279-6',278,'Wir suchen eine Wohnung, die günstig ist.','de'),
('de-l280-1',279,'Das ist der Film, den ich mag.','de'),
('de-l280-2',279,'Das ist die Tasche, die ich gekauft habe.','de'),
('de-l280-3',279,'Das ist das Buch, das du suchst.','de'),
('de-l280-4',279,'Das sind die Schuhe, die ich brauche.','de'),
('de-l280-5',279,'Der Mann, den wir kennen, kommt heute.','de'),
('de-l280-6',279,'Die Stadt, die wir besuchen, ist schön.','de'),
('de-l281-1',280,'Wenn es regnet, bleibe ich zu Hause.','de'),
('de-l281-2',280,'Wenn du Zeit hast, ruf mich an.','de'),
('de-l281-3',280,'Ich höre Musik, wenn ich koche.','de'),
('de-l281-4',280,'Wenn der Bus kommt, steigen wir ein.','de'),
('de-l281-5',280,'Wenn ich müde bin, trinke ich Tee.','de'),
('de-l281-6',280,'Wir gehen spazieren, wenn das Wetter gut ist.','de'),
('de-l282-1',281,'Als ich ein Kind war, wohnte ich in Bonn.','de'),
('de-l282-2',281,'Als wir ankamen, war es dunkel.','de'),
('de-l282-3',281,'Ich war müde, als ich nach Hause kam.','de'),
('de-l282-4',281,'Als sie anrief, habe ich gekocht.','de'),
('de-l282-5',281,'Als der Film begann, waren alle still.','de'),
('de-l282-6',281,'Wir haben uns kennengelernt, als ich studiert habe.','de'),
('de-l283-1',282,'Ich wasche meine Hände, bevor ich esse.','de'),
('de-l283-2',282,'Ruf mich an, bevor du gehst.','de'),
('de-l283-3',282,'Wir kaufen Tickets, bevor wir fahren.','de'),
('de-l283-4',282,'Nachdem ich gegessen habe, gehe ich spazieren.','de'),
('de-l283-5',282,'Nachdem der Kurs zu Ende ist, fahren wir nach Hause.','de'),
('de-l283-6',282,'Nachdem sie angekommen war, hat sie mich angerufen.','de'),
('de-l284-1',283,'Obwohl es regnet, gehen wir spazieren.','de'),
('de-l284-2',283,'Ich komme, obwohl ich wenig Zeit habe.','de'),
('de-l284-3',283,'Sie lernt, obwohl sie müde ist.','de'),
('de-l284-4',283,'Es regnet. Trotzdem gehen wir spazieren.','de'),
('de-l284-5',283,'Ich bin müde. Trotzdem lerne ich weiter.','de'),
('de-l284-6',283,'Der Weg ist lang. Trotzdem fahren wir mit dem Fahrrad.','de'),
('de-l285-1',284,'Ich versuche, Deutsch zu sprechen.','de'),
('de-l285-2',284,'Es ist wichtig, regelmäßig zu üben.','de'),
('de-l285-3',284,'Ich habe vergessen, Brot zu kaufen.','de'),
('de-l285-4',284,'Sie beginnt, ein Buch zu lesen.','de'),
('de-l285-5',284,'Ich versuche, früh aufzustehen.','de'),
('de-l285-6',284,'Wir haben vor, morgen einzukaufen.','de'),
('de-l286-1',285,'Ich lerne Deutsch, um in Berlin zu arbeiten.','de'),
('de-l286-2',285,'Wir gehen früh los, um den Zug zu erreichen.','de'),
('de-l286-3',285,'Sie spart Geld, um ein Fahrrad zu kaufen.','de'),
('de-l286-4',285,'Ich rufe an, um einen Termin zu vereinbaren.','de'),
('de-l286-5',285,'Er trägt eine Brille, um besser zu sehen.','de'),
('de-l286-6',285,'Wir üben jeden Tag, um sicherer zu sprechen.','de'),
('de-l287-1',286,'Ich spreche langsam, damit du mich verstehst.','de'),
('de-l287-2',286,'Ich schicke dir die Adresse, damit du uns findest.','de'),
('de-l287-3',286,'Wir machen das Licht an, damit alle sehen können.','de'),
('de-l287-4',286,'Sie erklärt die Regel, damit wir sie verstehen.','de'),
('de-l287-5',286,'Ich schreibe es auf, damit ich es nicht vergesse.','de'),
('de-l287-6',286,'Er öffnet das Fenster, damit frische Luft hereinkommt.','de'),
('de-l288-1',287,'Wissen Sie, wo der Bahnhof ist?','de'),
('de-l288-2',287,'Kannst du mir sagen, wann der Zug fährt?','de'),
('de-l288-3',287,'Ich weiß nicht, wie viel das kostet.','de'),
('de-l288-4',287,'Ich frage mich, ob sie heute kommt.','de'),
('de-l288-5',287,'Können Sie mir sagen, ob der Laden offen ist?','de'),
('de-l288-6',287,'Ich möchte wissen, warum er wartet.','de'),
('de-l289-1',288,'Ich wasche mich.','de'),
('de-l289-2',288,'Du erinnerst dich an den Tag.','de'),
('de-l289-3',288,'Sie freut sich auf die Reise.','de'),
('de-l289-4',288,'Wir treffen uns morgen.','de'),
('de-l289-5',288,'Ihr beeilt euch.','de'),
('de-l289-6',288,'Ich ziehe mir die Jacke an.','de'),
('de-l290-1',289,'Ich warte auf den Bus.','de'),
('de-l290-2',289,'Sie interessiert sich für Musik.','de'),
('de-l290-3',289,'Wir sprechen über den Film.','de'),
('de-l290-4',289,'Er denkt an seine Familie.','de'),
('de-l290-5',289,'Ich freue mich über das Geschenk.','de'),
('de-l290-6',289,'Sie nimmt an einem Kurs teil.','de'),
('de-l291-1',290,'Worauf wartest du?','de'),
('de-l291-2',290,'Ich warte darauf.','de'),
('de-l291-3',290,'Woran denkst du?','de'),
('de-l291-4',290,'Ich denke daran.','de'),
('de-l291-5',290,'Wofür interessierst du dich?','de'),
('de-l291-6',290,'Ich interessiere mich dafür.','de'),
('de-l292-1',291,'Ich war gestern zu Hause.','de'),
('de-l292-2',291,'Wir hatten wenig Zeit.','de'),
('de-l292-3',291,'Sie konnte nicht kommen.','de'),
('de-l292-4',291,'Ich musste früh aufstehen.','de'),
('de-l292-5',291,'Er wollte Arzt werden.','de'),
('de-l292-6',291,'Du durftest dort spielen.','de'),
('de-l293-1',292,'Ich hatte schon gegessen.','de'),
('de-l293-2',292,'Sie war bereits gegangen.','de'),
('de-l293-3',292,'Wir hatten die Tickets gekauft.','de'),
('de-l293-4',292,'Er hatte den Schlüssel vergessen.','de'),
('de-l293-5',292,'Nachdem wir angekommen waren, riefen wir an.','de'),
('de-l293-6',292,'Ich war müde, weil ich schlecht geschlafen hatte.','de'),
('de-l294-1',293,'Könnten Sie das wiederholen?','de'),
('de-l294-2',293,'Ich hätte gern einen Tee.','de'),
('de-l294-3',293,'Es wäre schön, dich zu sehen.','de'),
('de-l294-4',293,'Würdest du mir helfen?','de'),
('de-l294-5',293,'Wenn ich Zeit hätte, würde ich mitkommen.','de'),
('de-l294-6',293,'An deiner Stelle würde ich warten.','de'),
('de-l295-1',294,'Die Tür wird geöffnet.','de'),
('de-l295-2',294,'Das Haus wird gebaut.','de'),
('de-l295-3',294,'Die Tickets werden kontrolliert.','de'),
('de-l295-4',294,'Hier wird Deutsch gesprochen.','de'),
('de-l295-5',294,'Der Brief wurde gestern geschickt.','de'),
('de-l295-6',294,'Das Zimmer muss gereinigt werden.','de'),
('de-l296-1',295,'Ich trinke entweder Tee oder Kaffee.','de'),
('de-l296-2',295,'Sie spricht sowohl Deutsch als auch Englisch.','de'),
('de-l296-3',295,'Wir haben weder Zeit noch Geld.','de'),
('de-l296-4',295,'Das ist nicht nur günstig, sondern auch praktisch.','de'),
('de-l296-5',295,'Je mehr ich übe, desto sicherer werde ich.','de'),
('de-l296-6',295,'Einerseits ist es teuer, andererseits ist es nützlich.','de'),
('de-l297-1',296,'Ich suche eine Wohnung, die in der Nähe des Bahnhofs liegt.','de'),
('de-l297-2',296,'Das wäre praktisch, weil ich jeden Tag mit dem Zug fahre.','de'),
('de-l297-3',296,'Obwohl die Wohnung klein ist, gefällt sie mir.','de'),
('de-l297-4',296,'Ich möchte wissen, ob die Heizung gut funktioniert.','de'),
('de-l297-5',296,'Bevor ich mich entscheide, möchte ich sie besichtigen.','de'),
('de-l297-6',296,'Könnten Sie mir sagen, wann eine Besichtigung möglich wäre?','de')
